from pathlib import Path
root=Path(__file__).resolve().parents[2]
s=(root/'index.html').read_text()
s=s.replace("KEY='gametrace_saved_games_v12'","KEY='gametrace_v42_QA'").replace("PREVIOUS_KEY='gametrace_saved_games_v11'","PREVIOUS_KEY='gametrace_v42_QA_previous'").replace("DB_NAME='gametrace-video-library-v1'","DB_NAME='gametrace-v42-QA-video'")
setup=r'''
/* Isolated sample fixture. Never included in the production build. */
window.fetch=async()=>{throw Error('QA has no external network access')};
const qaNow=C.now(),qaAt=n=>new Date(Date.now()-600000+n*1000).toISOString(),qaGame=C.prepareGame({player:'Georgina',team:'North Jersey Elite',opponent:'Caldwell',date:localDate()});C.startGame(qaGame,qaAt(0));C.appendEvent(qaGame,'in',{at:qaAt(1)});C.appendEvent(qaGame,'3_make',{at:qaAt(15)});C.appendEvent(qaGame,'2_make',{at:qaAt(30)});C.appendEvent(qaGame,'reb_d',{at:qaAt(45)});C.appendEvent(qaGame,'assist',{at:qaAt(55)});C.appendEvent(qaGame,'opponent_2',{at:qaAt(75)});C.appendEvent(qaGame,'score_set',{at:qaAt(90),scoreTeam:38,scoreOpponent:34});
const qaComplete=C.clone(qaGame);qaComplete.id='qa-completed';qaComplete.opponent='Opponent with a longer basketball academy name';C.finishGame(qaComplete,{at:qaAt(120),score:{team:42,opponent:36}});
const qaDB=C.blankDB();qaDB.games=[qaGame,qaComplete];qaDB.activeGameId=qaGame.id;qaDB.trainingSessions=['Shooting','Open Gym Shooting DTS','Long training title to verify aligned columns'].map((name,i)=>T.validSession({id:'qa-session-'+i,type:'training',name,date:localDate(),minutes:60,player:'Georgina',tags:['Shooting','Ball handling'],awardEligible:true,createdAt:qaNow,updatedAt:qaNow}));qaDB.goals=['Attack open space','Finish confidently through contact'].map((title,i)=>T.validGoal({id:'qa-goal-'+i,title,player:'Georgina',status:'active',entries:[],createdAt:qaNow,updatedAt:qaNow}));qaDB.personalRecords=J.records(['game','training','camp'].map((activity,i)=>({id:'qa-event-'+i,type:'schedule',activity,title:['Panthers matchup','Skills training','Elite camp'][i],team:activity==='game'?'North Jersey Elite':'',opponent:activity==='game'?'Caldwell':'',player:'Georgina',start:new Date(Date.now()+86400000*(i+1)).toISOString(),createdAt:qaNow,updatedAt:qaNow})));localStorage.setItem(C.KEY,JSON.stringify(C.validDB(qaDB)));
familyAuth={access_token:'qa-only',refresh_token:'qa-only',expires_at:Date.now()+3600000,user:{id:'qa-viewer'}};familyState={familyId:'11111111-1111-1111-1111-111111111111',baseline:{},clips:{},autoUpload:false,wifiOnly:true};familyContext={display_name:'Family',family:{id:familyState.familyId,name:'Family',role:'member'},families:[],members:[{display_name:'Family',user_id:'qa-viewer',role:'member'}]};familyAccess=true;familyMembershipChecked=true;personalCloud=true;extendedPersonalCloud40=true;scheduleCloud41=true;verifyFamilyMembership=async()=>true;const qaRemote=qaDB.games.map(payload=>({kind:'game',record_id:payload.id,payload:C.clone(payload),version:1,updated_at:qaNow}));familyState.reviewedFor=familyReviewKey();for(const r of currentFamilyRecords())familyState.baseline[familyRecordKey(r)]={version:1,hash:fingerprint(r.payload)};
familyFetch=async(path,options={})=>{if(path.includes('/gt_records'))return path.includes('kind=eq.game')?qaRemote:qaRemote;if(path.endsWith('/gt_cloud_features'))return{version:9};if(path.endsWith('/gt_family_context'))return familyContext;if(path.endsWith('/gt_save_record'))return{conflict:false,record:{kind:options.body.record_kind,record_id:options.body.rid,payload:options.body.body,version:2}};return{ready:false,enabled:false,leadMinutes:60}};
'''
s=s.replace('\nload();\nwindow.GameTraceFamily.boot();','\n'+setup+'\nload();\nwindow.GameTraceFamily.boot();')
import sys
out=Path(sys.argv[1]);out.parent.mkdir(parents=True,exist_ok=True);out.write_text(s)
print('Created isolated browser QA fixture')
